import { useEffect, useState } from 'react'
import { Form, Input, Button, Select, Spin, notification } from 'antd'
import { useErrorContextValue, usePost, useLoaderContextValue, useResetState, useResetError } from '@pasarpolis/common-react-hooks'

import { staticOtpConfig } from '../apiConfig'
import { checkPhoneNumberIsValid } from '../../../../helpers/validator'
import { copyToClipboard } from '../../../../helpers/copyToClipboard'
import { StaticOtpWrapper, InputFormContainer, OtpDisplayBox, OtpText, ButtonWrapper, TextCenter, Wrapper } from './index.style'

const { Item } = Form
const { Option } = Select

function StaticOtp () {
  /* declaring states */
  const [recipientNumber, setRecipientNumber] = useState('')
  const [reason, setReason] = useState('')
  const [countryCode, setCountryCode] = useState('+62')
  const [data, staticOtpRequest] = usePost(staticOtpConfig.getStaticOtp)
  const [{
    STATIC_OTP_PROVIDER_ERROR,
    staticOtpProviderStatus,
    staticOtpProviderErrorData
  }] = useErrorContextValue()
  const { resetState } = useResetState()
  const { resetError } = useResetError()
  const [{ STATIC_OTP_PROVIDER_LOADER }] = useLoaderContextValue()

  /* declaring useEffects */

  /**
     *  to check whether to enable or disable viewOtp button
     */
  useEffect(() => {
    STATIC_OTP_PROVIDER_ERROR && notification.error({
      message: staticOtpProviderErrorData?.error || staticOtpProviderStatus
    })
  }, [STATIC_OTP_PROVIDER_ERROR, staticOtpProviderErrorData, staticOtpProviderStatus])

  const isButtonDisable = (countryCode && recipientNumber.trim() && reason.trim())
    ? checkPhoneNumberIsValid(recipientNumber)
    : true

  const recipientNumberInputChangeHandler = (event) => {
    const { value } = event.target
    setRecipientNumber(value)
  }

  const reasonInputChangeHandler = (event) => {
    const { value } = event.target
    setReason(value)
  }

  const viewOtpClickHandler = () => {
    const payload = {
      mobile_no: `${countryCode.slice(1)}-${recipientNumber}`,
      reason
    }
    staticOtpRequest(payload)
  }

  const countryCodeChangeHandler = (value) => {
    setCountryCode(value)
  }

  const copyOtpClickHandler = () => {
    const flag = copyToClipboard(data?.otp)
    if (flag) {
      notification.success({
        message: 'Otp is successfully copied to clipboard '
      })
    } else {
      notification.error({
        message: 'It seems there have been some issue'
      })
    }
  }

  const okButtonClickHandler = () => {
    setRecipientNumber('')
    setReason('')
    resetState(['staticOtpProviderData'])
    resetError(['STATIC_OTP_PROVIDER_ERROR', 'staticOtpProviderStatus', 'staticOtpProviderErrorData'])
  }

  /* for selcect options */
  const selectBefore = (
    <Select defaultValue={countryCode} className='select-before' onChange={countryCodeChangeHandler}>
      <Option value='+62'>+62</Option>
      <Option value='+91'>+91</Option>
      <Option value='+84'>+84</Option>
    </Select>
  )

  const showOtp = (
    <StaticOtpWrapper>
      <InputFormContainer>
        <TextCenter>Showing OTP for {recipientNumber}</TextCenter>
        <OtpDisplayBox>
          <OtpText>
            {data?.otp}
          </OtpText>
        </OtpDisplayBox>
        <ButtonWrapper>
          <Button type='primary' onClick={copyOtpClickHandler}>
            Copy OTP
          </Button>
          <Button type='primary' onClick={okButtonClickHandler}>
            OK
          </Button>
        </ButtonWrapper>
        <TextCenter>
          {
            data?.expires_at
              ? `OTP expires in ${data.expires_at} UTC`
              : ''
          }
        </TextCenter>
      </InputFormContainer>
    </StaticOtpWrapper>
  )

  const otoForm = (
    <StaticOtpWrapper>
      <InputFormContainer>
        <Item
          label='Enter recipient number'
        >
          <Input
            addonBefore={selectBefore}
            value={recipientNumber}
            onChange={recipientNumberInputChangeHandler}
          />
        </Item>
        <Item label='Reason'>
          <Input
            value={reason}
            onChange={reasonInputChangeHandler}
          />
        </Item>
        <Item>
          <TextCenter>
            <Button onClick={viewOtpClickHandler} disabled={isButtonDisable} type='primary'>
              View OTP
            </Button>
          </TextCenter>
        </Item>
      </InputFormContainer>
    </StaticOtpWrapper>
  )

  return (
    <Wrapper>
      <Spin
        spinning={!!STATIC_OTP_PROVIDER_LOADER}
      >
        {data?.otp
          ? showOtp
          : otoForm}
      </Spin>
    </Wrapper>

  )
}

export default StaticOtp
